// Normalisasi payload order dari berbagai sumber (Shopee, Tokopedia, Web MyGameON, dsb)
const payload = $input.first().json.body || $input.first().json;

const customerEmail = (payload.customerEmail || payload.email || payload.buyer_email || '').toLowerCase().trim();
const invoice = (payload.invoice || payload.order_id || payload.order_sn || `MGO-${Date.now().toString(36).toUpperCase()}`).trim();
const platform = payload.platform || (payload.order_sn ? 'shopee' : 'website');

// Format items agar selalu berupa array terstruktur
let items = [];
if (Array.isArray(payload.items) && payload.items.length > 0) {
  items = payload.items.map(item => typeof item === 'string' ? { name: item } : item);
} else if (payload.game_name || payload.product_name) {
  items = [{
    name: payload.game_name || payload.product_name,
    type: payload.type || (String(payload.product_name || '').toLowerCase().includes('sims') ? 'sims4' : 'game'),
    allowCC: payload.allowCC !== undefined ? payload.allowCC : true
  }];
}

return [{
  json: {
    customerEmail,
    invoice,
    platform,
    items,
    sendEmail: payload.sendEmail !== false,
    expirationDays: payload.expirationDays || null,
    notes: payload.notes || ''
  }
}];
